from typing import Callable, Hashable, Sequence, Tuple, TypeVar
S = TypeVar("S", bound=Hashable)
def targeted_filter(word: Sequence[S], retain: Callable[[S], bool]) -> Tuple[S, ...]:
    return tuple(x for x in word if retain(x))
if __name__ == "__main__":
    keep = lambda x: x in {"a", "c"}
    print("".join(targeted_filter(tuple("abbcba"), keep)))

from typing import Callable, Dict, Hashable, Tuple, TypeVar
S = TypeVar("S", bound=Hashable)
def collision(identity: S, transition: Callable[[S], S], number_of_states: int) -> Tuple[int, int, S]:
    seen: Dict[S, int] = {identity: 0}
    state = identity
    for j in range(1, number_of_states + 1):
        state = transition(state)
        if state in seen:
            return seen[state], j, state
        seen[state] = j
    raise RuntimeError("The supplied state bound is inconsistent")
if __name__ == "__main__":
    print(collision(0, lambda x: (x + 1) % 7, 7))

from collections import defaultdict
from itertools import product
from typing import Callable, DefaultDict, Dict, Hashable, List, Sequence, Tuple, TypeVar
A = TypeVar("A", bound=Hashable)
R = TypeVar("R", bound=Hashable)
def bounded_classes(alphabet: Sequence[A], bound: int, memory: Callable[[Tuple[A, ...]], R]) -> Dict[R, List[Tuple[A, ...]]]:
    groups: DefaultDict[R, List[Tuple[A, ...]]] = defaultdict(list)
    for n in range(bound + 1):
        for word in product(alphabet, repeat=n):
            groups[memory(word)].append(word)
    return dict(groups)
if __name__ == "__main__":
    print({k: len(v) for k, v in bounded_classes(("a", "b"), 5, lambda w: len(w) % 2).items()})

